'use strict';
const E=DndEngine;
const T=DndTheme, I=DndI18n, C=DndChecks, D=DndTray;
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>n>=0?'+'+n:String(n);
const icon=(name)=>{const shapes={character:'<path d="M12 3 4 7v6c0 4 8 8 8 8s8-4 8-8V7Z"/><path d="m8 12 3 3 5-6"/>',spells:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',inventory:'<path d="M5 7h14v14H5Z M8 7V5a4 4 0 0 1 8 0v2 M5 11h14 M9 15h6"/>',notes:'<path d="M5 3h14v18H5Z M8 7h8 M8 11h8 M8 15h5"/>',theme:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-3.5A1.5 1.5 0 0 1 15 15h2a4 4 0 0 0 4-4c0-4.4-4-8-9-8Z"/><circle cx="7" cy="11" r=".8"/><circle cx="10" cy="7" r=".8"/><circle cx="15" cy="7" r=".8"/><circle cx="17" cy="11" r=".8"/>',dice:'<path d="m12 2 9 5v10l-9 5-9-5V7Z M12 2 7 10l5 12 5-12Z M3 7l4 3h10l4-3 M3 17l4-7 M21 17l-4-7"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+shapes[name]+'</svg>'};
const navigation=[['character','Персонаж'],['spells','Заклинания'],['inventory','Инвентарь'],['notes','Заметки'],['dice','Кубики'],['theme','Тема']];
const locations=['Надето','Рюкзак','Тайник','У спутника'];
let state;let storageAvailable=true;
try{state=JSON.parse(localStorage.getItem('adventure-ledger-v1'))}catch{storageAvailable=false}
if(!state||!Array.isArray(state.characters)||!state.characters.length||!state.characters.every(c=>c&&E.editions[c.edition]&&Array.isArray(c.stats)&&Array.isArray(c.spells)&&Array.isArray(c.items))){state={characters:Object.keys(E.editions).map(e=>E.createCharacter(e)),active:null,history:[]};state.active=state.characters.find(c=>c.edition==='5e2014').id;}
if(!state.characters.some(c=>c.id===state.active))state.active=state.characters[0].id;
if(!Array.isArray(state.history))state.history=[];
state.diceCollection=state.diceCollection&&typeof state.diceCollection==='object'?state.diceCollection:{};
state.diceCollection.sides=Array.isArray(state.diceCollection.sides)?[...new Set(state.diceCollection.sides.filter(n=>Number.isInteger(n)&&n>=2&&n<=1000))]:[4,6,8,10,12,20,100];if(!state.diceCollection.sides.length)state.diceCollection.sides=[20];
state.diceCollection.presets=Array.isArray(state.diceCollection.presets)?state.diceCollection.presets:[{id:'check',name:'Проверка',formula:'1d20',mode:'normal'},{id:'two',name:'Два шестигранника',formula:'2d6',mode:'normal'},{id:'four',name:'Четыре шестигранника',formula:'4d6',mode:'normal'},{id:'fire',name:'Огненный шар',formula:'8d6',mode:'normal'}];
state.tray=D.normalize(state.tray);
state.checkSelection=typeof state.checkSelection==='string'?state.checkSelection:'skill:0';
state.checkSituation=E.integer(state.checkSituation,-99,99);
state.checkMode=['normal','advantage','disadvantage'].includes(state.checkMode)?state.checkMode:'normal';
for(const c of state.characters){c.effects=Array.isArray(c.effects)?c.effects:[];c.spellAbility=Number.isInteger(c.spellAbility)?c.spellAbility:3;c.spellAttackAdjustment??=c.spellAttack-(E.modifier(c.stats[c.spellAbility])+c.proficiency);c.initiativeAdjustment??=c.initiative-E.modifier(c.stats[1]);}
state.theme=T.normalize(state.theme);
state.language=['ru','en','bilingual'].includes(state.language)?state.language:'ru';
let tab=['character','spells','inventory','notes','dice','theme'].includes(location.hash.slice(1))?location.hash.slice(1):'character';
let selectedDie=state.diceCollection.sides.includes(20)?20:state.diceCollection.sides[0],spellFilter='all',spellQuery='',inventoryFilter='all',combat=false,toastTimer,lastTrayRoll=null;
const character=()=>state.characters.find(c=>c.id===state.active);
const tr=value=>I.text(value,state.language);
function translated(html){const names=Object.fromEntries([...character().spells,...character().items].filter(x=>x.englishName).map(x=>[x.name,esc(x.englishName)]));return I.html(html,state.language,names)}
function applyTheme(){T.apply(state.theme,document)}
function refreshLanguage(){
$('#language').value=state.language;
for(const [selector,text]of [['.brand-second','приключений'],['.side-label','ВАШЕ ПРИКЛЮЧЕНИЕ'],['.edition-control>span','Правила'],['.language-control>span','Язык'],['.eyebrow','КАЖДЫЙ БРОСОК — НОВАЯ ИСТОРИЯ'],['#new-character','＋ Новый персонаж'],['#edit-character','Изменить персонажа ↗'],['#rest','☾ Отдых'],['#export','Экспорт персонажа ↗'],['.hero-kicker','ГОТОВ К ПРИКЛЮЧЕНИЮ'],['.sidebar-bottom p','История начинается за вашим столом.'],['.dice-panel h3','Быстрый бросок'],['.dice-panel .tiny-label','СУДЬБА В ВАШИХ РУКАХ'],['.table-note strong','Играйте за живым столом'],['.table-note p','Можно бросать настоящие кубики. Лист поможет с бонусами и ресурсами.'],['footer>span:first-child','Лист приключений'],['.dice-count-label','Кубиков'],['.dice-mod-label','Бонус'],['.history-label','ПОСЛЕДНИЕ БРОСКИ'],['#clear-history','Очистить'],['.quick-presets-title','МОИ ПРЕСЕТЫ']]){const node=$(selector);if(node)node.textContent=tr(text)}
const oldMode=$('#roll-mode').value||'normal';$('#roll-mode').innerHTML=['normal','advantage','disadvantage'].map((v,i)=>'<option value="'+v+'">'+tr(['Обычный бросок','С преимуществом · d20','С помехой · d20'][i])+'</option>').join('');$('#roll-mode').value=oldMode;
$('#roll-result').innerHTML=translated('<span>Сделайте первый бросок</span><small>История сохраняется для каждого персонажа</small>');
}
function save(){try{localStorage.setItem('adventure-ledger-v1',JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false}$('#save-indicator').innerHTML=storageAvailable?'<i></i> '+tr('Сохранено на устройстве'):'⚠ Изменения только до закрытия вкладки';}
function toast(message){$('#toast').textContent=tr(message);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
const button=(action,label,classes='text-button',extra='')=>'<button class="'+classes+'" data-action="'+action+'" '+extra+'>'+label+'</button>';
function portrait(){return '<svg viewBox="0 0 110 125" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="hood" x2="0" y2="1"><stop stop-color="#809072"/><stop offset="1" stop-color="#334c37"/></linearGradient></defs><circle cx="55" cy="52" r="39" fill="none" stroke="#b5b88c" stroke-width=".6"/><circle cx="55" cy="52" r="32" fill="none" stroke="#b5b88c" stroke-width=".5"/><path d="M7 125c3-26 24-32 29-39L24 60 38 23 55 10 74 26 87 60 75 88c15 8 23 18 28 37" fill="url(#hood)" stroke="#a2aa7e" stroke-width=".8"/><path d="m33 61 9-27 14-12 13 14 9 25-14 28H46Z" fill="#172d25"/><path d="m43 49 6-8h17l5 12-7 22-11 4-11-15Z" fill="#a6ad89"/><path d="m42 49 14-22 17 27-17-10Z" fill="#425c40"/><path d="m44 61 11 15 10-5-8 22-12-10Z" fill="#d1c6a0"/><path d="m28 89 25 21 27-22 M33 108l-7 17 M78 109l8 16" fill="none" stroke="#b5ba8b" stroke-width="1"/><path d="m55 102 6 9-6 9-6-9Z" fill="#d1b984"/><path d="m91 14 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#cabb8f"/></svg>'}
function render(){applyTheme();const c=character();document.body.classList.toggle('combat',combat&&tab==='character');$('#side-name').textContent=c.name;$('#side-level').textContent=tr(c.className+' · '+c.level+' уровень');$('#hero-name').textContent=c.name;$('#hero-meta').textContent=tr(c.className+' · Уровень '+c.level+' · '+c.race);$('#hero-edition').textContent=E.editions[c.edition];$('#hero-classification').textContent=tr(c.demo?'Демонстрационный персонаж':'Ваш персонаж');$('#language').value=state.language;$('#edition').value=c.edition;$('#portrait').innerHTML=portrait();const title={character:['Ваш персонаж','Всё, что нужно для следующего приключения.'],spells:['Книга заклинаний','Магия под рукой. Следите за ячейками и концентрацией.'],inventory:['Ваш инвентарь','Каждая находка на своём месте.'],notes:['Дневник приключений','Важные имена, зацепки и немного вашей истории.'],dice:['Пусть решат кубики','От простой проверки до собственного броска.'],theme:['Ваша тема','Подберите цвета под своё приключение.']}[tab];$('#page-title').textContent=tr(title[0]);$('#page-subtitle').textContent=tr(title[1]);$('#page-crumb').textContent=tr(navigation.find(n=>n[0]===tab)[1]);for(const selector of ['#main-nav','#mobile-nav'])$(selector).innerHTML=navigation.map(([id,label])=>'<button class="nav-item '+(tab===id?'active':'')+'" data-action="tab" data-id="'+id+'" '+(tab===id?'aria-current="page"':'')+'>'+icon(id)+'<span>'+tr(label)+'</span></button>').join('');$('#view').innerHTML={character:characterView,spells:spellsView,inventory:inventoryView,notes:notesView,dice:diceView,theme:themeView}[tab]();$('#view').innerHTML=translated($('#view').innerHTML);renderHistory();if(tab==='dice'){renderTrayResult(lastTrayRoll,false);renderCheckSummary()}if(tab==='theme')for(const [key]of T.fields)syncThemeControls(key);save()}

function englishField(value){return '<label class="form-field wide">Английское название<input name="englishName" value="'+esc(value)+'" maxlength="100" placeholder="Необязательно / Optional"></label>'}
function themeView(){const t=state.theme;const active=Object.entries(T.presets).find(([,p])=>Object.keys(T.defaults).every(k=>t[k]===p[k]))?.[0];return '<section class="panel theme-intro"><div><h3>Подберите цвета под своё приключение.</h3><p>Цвета меняются сразу. Текст подбирается автоматически, чтобы лист оставался читаемым.</p></div><div class="theme-sigil">'+icon('theme')+'</div></section><div class="section-heading"><h3>Готовые палитры</h3></div><div class="theme-presets">'+Object.entries(T.presets).map(([id,p])=>button('theme-preset','<div class="preset-swatches">'+['background','primary','light','accent'].map(k=>'<span style="background:'+p[k]+'"></span>').join('')+'</div><strong>'+p.name+'</strong><small>'+p.description+'</small>','theme-preset '+(id===active?'active':''),'data-id="'+id+'" aria-pressed="'+(id===active)+'"')).join('')+'</div><div class="theme-colors">'+T.fields.map(([key,label,desc])=>{const channels=T.rgb(t[key]);return '<section class="panel color-editor"><div class="color-editor-heading"><input class="color-swatch" type="color" value="'+t[key]+'" data-theme-field="'+key+'" data-theme-kind="picker" aria-label="'+esc(label)+'"><div><h3>'+label+'</h3><p>'+desc+'</p></div><input class="color-hex" value="'+t[key]+'" maxlength="7" pattern="#[a-fA-F0-9]{6}" data-theme-field="'+key+'" data-theme-kind="hex" aria-label="HEX: '+label+'"></div>'+['R','G','B'].map((channel,i)=>'<label class="rgb-row"><span>'+channel+'</span><input type="range" min="0" max="255" step="1" value="'+channels[i]+'" data-theme-field="'+key+'" data-theme-kind="channel" data-channel="'+i+'" aria-label="'+esc(label)+' '+channel+'"><input type="number" min="0" max="255" step="1" value="'+channels[i]+'" data-theme-field="'+key+'" data-theme-kind="channel" data-channel="'+i+'" aria-label="'+esc(label)+' '+channel+' 0–255"></label>').join('')+'</section>'}).join('')+'</div><section class="panel theme-style-panel"><div class="theme-control-grid"><div><span class="theme-control-title">Стиль иконок</span><div class="theme-style-choices">'+[['thin','Тонкие'],['outline','Контурные'],['bold','Выразительные']].map(([id,label])=>button('theme-icon-style',label,'theme-style-choice '+(t.iconStyle===id?'active':''),'data-id="'+id+'" aria-pressed="'+(t.iconStyle===id)+'"')).join('')+'</div><div class="icon-preview">'+['character','spells','inventory','dice','theme'].map(icon).join('')+'</div></div><div><span class="theme-control-title">Узор фона</span><div class="theme-style-choices">'+[['plain','Без узора'],['paper','Бумага'],['runes','Рунная сетка']].map(([id,label])=>button('theme-pattern',label,'theme-style-choice '+(t.pattern===id?'active':''),'data-id="'+id+'" aria-pressed="'+(t.pattern===id)+'"')).join('')+'</div></div></div><p class="theme-hint">Для контраста текст и слишком бледные иконки подстраиваются под фон.</p></section>'+themeEffectsView()+'<section class="panel theme-style-panel"><span class="theme-control-title">Язык интерфейса и названий</span><div class="theme-style-choices">'+[['ru','Русский'],['en','English'],['bilingual','Русский + English']].map(([id,label])=>button('language',label,'theme-style-choice '+(state.language===id?'active':''),'data-id="'+id+'" aria-pressed="'+(state.language===id)+'"')).join('')+'</div><p class="theme-hint">В двойном режиме игровые названия показываются на двух языках.</p></section><div class="theme-bottom"><p>Тема сохранена в этом браузере.</p>'+button('theme-reset','Сбросить тему','outline-button')+'</div>'}
function themeEffectsView(){const t=state.theme;return '<section class="panel theme-style-panel"><div class="section-heading"><h3>Переливы и стекло</h3><span class="tiny-label">ВАША АТМОСФЕРА</span></div><div class="theme-control-grid"><div><span class="theme-control-title">Фон</span><div class="theme-style-choices">'+[['plain','Однотонный'],['gradient','Градиент'],['aurora','Сияние']].map(([id,label])=>button('theme-atmosphere',label,'theme-style-choice '+(t.atmosphere===id?'active':''),'data-id="'+id+'" aria-pressed="'+(t.atmosphere===id)+'"')).join('')+'</div></div><div><span class="theme-control-title">Карточки</span><div class="theme-style-choices">'+[['solid','Обычные'],['glass','Стекло']].map(([id,label])=>button('theme-panels',label,'theme-style-choice '+(t.panels===id?'active':''),'data-id="'+id+'" aria-pressed="'+(t.panels===id)+'"')).join('')+'</div></div></div><div class="effect-sliders">'+[['angle','Угол градиента',0,360,'°'],['glassBlur','Размытие стекла',0,30,' px'],['glassOpacity','Плотность стекла',72,100,'%']].map(([key,label,min,max,unit])=>'<label class="effect-slider"><span>'+label+' <output id="effect-'+key+'">'+t[key]+unit+'</output></span><input type="range" min="'+min+'" max="'+max+'" step="1" value="'+t[key]+'" data-theme-setting="'+key+'" data-unit="'+unit+'"></label>').join('')+'</div>'+button('theme-motion',(t.motion?'✓ ':'')+'Плавное движение сияния','theme-style-choice '+(t.motion?'active':''),'aria-pressed="'+t.motion+'"')+'<p class="theme-hint">Стекло лучше видно на градиенте или сиянии. Движение отключается, если на устройстве уменьшена анимация.</p></section>'}
function updateThemeSetting(el){const key=el.dataset.themeSetting;if(!['angle','glassBlur','glassOpacity'].includes(key))return;state.theme[key]=Number(el.value);state.theme=T.normalize(state.theme);applyTheme();$('#effect-'+key).textContent=state.theme[key]+(el.dataset.unit||'');save()}

function syncThemeControls(key,clearPreset=false){const values=T.rgb(state.theme[key]);for(const el of document.querySelectorAll('[data-theme-field="'+key+'"]')){const value=el.dataset.themeKind==='channel'?values[Number(el.dataset.channel)]:state.theme[key];if(el.value!==String(value))el.value=String(value)}if(clearPreset)for(const el of document.querySelectorAll('.theme-preset')){el.classList.remove('active');el.setAttribute('aria-pressed','false')}for(const el of document.querySelectorAll('.rgb-row input[type="range"]')){const v=T.rgb(state.theme[el.dataset.themeField]),i=Number(el.dataset.channel),from=v.slice(),to=v.slice();from[i]=0;to[i]=255;el.style.background='linear-gradient(to right,'+T.hex(from)+','+T.hex(to)+')'}}
function updateThemeInput(el){const key=el.dataset.themeField;if(!T.fields.some(([k])=>k===key))return;let color;if(el.dataset.themeKind==='channel'){if(el.value==='')return;const values=T.rgb(state.theme[key]);values[Number(el.dataset.channel)]=E.integer(el.value,0,255);color=T.hex(values)}else{color=el.value.trim();if(!/^#[a-fA-F0-9]{6}$/.test(color))return}state.theme[key]=color.toLowerCase();applyTheme();syncThemeControls(key,true);save()}

function characterView(){const c=character(),old=c.edition==='3.5';const saves=old?['Стойкость','Рефлексы','Воля'].map((name,i)=>{const n=C.calculate(c,'save:'+i).bonus;return button('save',esc(name)+' <b>'+signed(n)+'</b>','save-button','data-index="'+i+'"')}):E.labels.map((name,i)=>button('save',name+' <b>'+signed(C.calculate(c,'save:'+i).bonus)+'</b>','save-button','data-index="'+i+'"'));
return '<div class="inline-toolbar">'+button('picker','Мои персонажи ⌄','text-button')+'<div>'+button('edit-character','Изменить','text-button')+' &nbsp; '+button('combat',combat?'Все показатели':'За столом ↗','outline-button')+'</div></div><div class="vitals"><button class="vital" data-action="edit-character"><strong>'+c.ac+'</strong><span>Класс доспеха</span></button><button class="vital" data-action="initiative"><strong>'+signed(C.calculate(c,'initiative').bonus)+'</strong><span>Инициатива ↗</span></button><button class="vital" data-action="edit-character"><strong>'+c.speed+'<small> м</small></strong><span>Скорость</span></button></div><section class="panel hp-panel"><div class="hp-header"><div><span class="hp-title">♡ Здоровье</span><div class="hp-numbers">'+c.hp+' <small>/ '+c.maxHp+'</small></div></div>'+button('rest','☾ Отдых','text-button')+'</div><div class="hp-meter" role="progressbar" aria-label="Хиты" aria-valuemin="0" aria-valuemax="'+c.maxHp+'" aria-valuenow="'+c.hp+'"><div style="width:'+(c.hp/c.maxHp*100)+'%"></div></div><div class="hp-controls"><input id="hp-amount" type="number" min="1" max="999" value="5" aria-label="Количество урона или лечения">'+button('damage','− Урон','damage')+button('heal','＋ Лечение')+button('temp-hp','Временные: '+c.tempHp,'temp-hp')+'</div></section><div class="ability-grid">'+E.labels.map((name,i)=>button('ability','<span>'+name+'</span><strong>'+c.stats[i]+'</strong><small>'+signed(E.modifier(c.stats[i]))+'</small>','ability','data-index="'+i+'" aria-label="Проверка: '+name+'"')).join('')+'</div><div class="two-columns"><div class="stack"><section class="panel"><div class="section-heading"><h3>Атаки и действия</h3><span class="tiny-label">'+(old?'БАБ '+signed(c.baseAttack):'МАСТЕРСТВО '+signed(c.proficiency))+'</span></div><div class="attack-item"><span class="attack-icon">⚔</span><div><strong>Посох</strong><small>Ближний бой · 1d6 '+signed(E.modifier(c.stats[0]))+'</small></div>'+button('attack','d20 '+signed(C.calculate(c,'attack:staff').bonus),'attack-roll','data-id="staff"')+'</div><div class="attack-item"><span class="attack-icon">✧</span><div><strong>Атака заклинанием</strong><small>'+(old?'Базовый бонус атаки + ловкость':'Заклинательная характеристика')+'</small></div>'+button('attack','d20 '+signed(C.calculate(c,'attack:spell').bonus),'attack-roll','data-id="spell"')+'</div><div class="resource-line"><span>Сл спасброска заклинаний</span><strong>'+(old?10+E.modifier(c.stats[3])+' + ур.':c.spellDC)+'</strong></div></section><section class="panel skills-panel"><div class="section-heading"><h3>'+(old?'Умения':'Навыки')+'</h3>'+button('edit-skills','Изменить')+'</div><div class="skills-list">'+c.skills.map((s,i)=>{const bonus=C.calculate(c,'skill:'+i).bonus;return button('skill','<span class="skill-dot '+((old?s.rank>0:s.trained)?'trained':'')+'"></span><span>'+esc(s.name)+'</span><span class="skill-ability">'+E.labels[s.stat].slice(0,3).toUpperCase()+'</span><b class="skill-bonus">'+signed(bonus)+'</b>','skill-row','data-index="'+i+'"')}).join('')+'</div></section></div><div class="stack"><section class="panel"><div class="section-heading"><h3>Спасброски</h3></div><div class="save-grid">'+saves.join('')+'</div></section><section class="panel"><div class="section-heading"><h3>Ресурсы</h3>'+button('slots','Изменить')+'</div>'+Object.entries(c.slots).filter(([n,s])=>s.max>0).map(([n,s])=>'<div class="resource-line"><span>Ячейки '+n+' уровня</span><div class="pips">'+Array.from({length:s.max},(_,i)=>button('slot', '', 'pip '+(i<s.used?'spent':''),'data-level="'+n+'" data-index="'+i+'" aria-label="Ячейка '+n+' уровня: '+(i<s.used?'восстановить':'потратить')+'"')).join('')+'</div></div>').join('')+'<div class="resource-line"><span>'+esc(c.resource.name)+'</span>'+button('resource',c.resource.max-c.resource.used+' / '+c.resource.max,'attack-roll')+'</div>'+(!old?'<div class="resource-line"><span>Кости хитов</span><b>'+Math.max(0,c.hitDice.max-c.hitDice.used)+'d'+c.hitDice.sides+'</b></div>':'')+'</section><section class="panel"><div class="section-heading"><h3>Ваш ход</h3>'+button('reset-turn','Новый ход')+'</div><div class="turn-actions">'+[['action','Действие'],...(!old?[['bonus','Бонусное']]:[['bonus','Передвижение']]),['reaction',old?'Быстрое':'Реакция']].map(([id,label])=>button('turn',label,'turn-action '+(c.turn[id]?'used':''),'data-id="'+id+'" aria-pressed="'+c.turn[id]+'"')).join('')+'</div><div class="section-heading" style="margin:18px 0 8px"><span class="muted">Состояния</span>'+button('conditions','＋ Добавить')+'</div><div class="condition-tags">'+(c.conditions.length?c.conditions.map(name=>button('remove-condition',esc(name)+' ×','condition-chip','data-id="'+esc(name)+'"')).join(''):'<span class="muted">Всё в порядке</span>')+'</div></section></div></div>'}
function spellsView(){const c=character();const spells=c.spells.filter(s=>(spellFilter==='all'||spellFilter==='prepared'&&s.prepared||String(s.level)===spellFilter)&&s.name.toLowerCase().includes(spellQuery.toLowerCase()));return '<div class="inline-toolbar"><h3>Ваши заклинания</h3>'+button('new-spell','＋ Заклинание','outline-button')+'</div><section class="panel slots-panel"><div class="section-heading"><h3>Ячейки заклинаний</h3>'+button('slots','Настроить')+'</div><div class="slot-grid">'+Object.entries(c.slots).filter(([n,s])=>s.max>0).map(([n,s])=>'<div class="slot-group">'+n+' УРОВЕНЬ · '+(s.max-s.used)+' / '+s.max+'<div>'+Array.from({length:s.max},(_,i)=>button('slot',i<s.used?'−':'✦','slot-pip '+(i<s.used?'spent':''),'data-level="'+n+'" data-index="'+i+'" aria-label="'+(i<s.used?'Восстановить':'Потратить')+' ячейку '+n+' уровня"')).join('')+'</div></div>').join('')+'</div>'+(c.edition==='3.5'?'<p class="edition-warning">Общий счётчик ячеек. Подготовку конкретных заклинаний в 3.5 пока отмечайте вручную.</p>':'')+'</section>'+(c.concentration?'<div class="concentration-banner">✧ Концентрация: <strong>'+esc(c.concentration)+'</strong>'+button('end-concentration','Завершить')+'</div>':'')+'<input class="search-input" id="spell-search" placeholder="Поиск по вашей книге…" aria-label="Поиск заклинаний" value="'+esc(spellQuery)+'"><div class="filters">'+[['all','Все'],['prepared','Подготовленные'],['0','Заговоры'],['1','1 уровень'],['2','2 уровень'],['3','3 уровень']].map(([id,label])=>button('spell-filter',label,'filter-button '+(spellFilter===id?'active':''),'data-id="'+id+'"')).join('')+'</div><div class="spell-grid" id="spell-grid">'+(spells.length?spells.map(s=>'<article class="spell-card"><div class="spell-card-top"><span class="spell-symbol">'+(s.damage?'✧':'✦')+'</span>'+button('prepare',s.prepared?'✓ Подготовлено':'Подготовить','prepare-button '+(s.prepared?'selected':''),'data-id="'+esc(s.id)+'"')+'</div><div class="spell-school">'+(s.level===0?(c.edition==='3.5'?'0 УРОВЕНЬ':'ЗАГОВОР'):s.level+' УРОВЕНЬ')+' · '+esc(s.school.toUpperCase())+'</div><h3>'+esc(s.name)+'</h3><div class="spell-info"><span>◷ '+esc(s.time)+'</span><span>↗ '+esc(s.range)+'</span>'+(s.concentration?'<span>◎ Конц.</span>':'')+'</div><p>'+esc(s.desc)+'</p><div class="spell-actions">'+button('cast',s.level===0&&c.edition!=='3.5'?'Использовать':'Сотворить','spell-button','data-id="'+esc(s.id)+'"')+button('spell-details','Подробнее','spell-details','data-id="'+esc(s.id)+'"')+'</div></article>').join(''):'<div class="empty-state">Заклинания не найдены. Добавьте свою карточку.</div>')+'</div>'}
function inventoryView(){const c=character(),items=c.items.filter(i=>inventoryFilter==='all'||i.location===inventoryFilter);return '<div class="inline-toolbar"><h3>Снаряжение и находки</h3>'+button('new-item','＋ Предмет','outline-button')+'</div><div class="inventory-summary"><div class="summary-box"><span>Общий вес вещей</span><strong>'+E.inventoryWeight(c.items).toLocaleString('ru-RU',{maximumFractionDigits:2})+' кг</strong></div><button class="summary-box" data-action="money"><span>Золотые монеты</span><strong>'+c.money+' <small> зм</small></strong></button></div><div class="filters">'+['all',...locations].map(id=>button('inventory-filter',id==='all'?'Все вещи':id,'filter-button '+(inventoryFilter===id?'active':''),'data-id="'+esc(id)+'"')).join('')+'</div><div class="inventory-table"><div class="inventory-head"><span>ПРЕДМЕТ</span><span>ХРАНЕНИЕ</span><span>КОЛ-ВО</span><span>ВЕС</span><span></span></div>'+ (items.length?items.map(i=>'<div class="inventory-row"><div class="inventory-name"><span class="item-icon">'+(i.category==='Оружие'?'⚔':i.category==='Расходник'?'♜':'◇')+'</span><button data-action="item-details" data-id="'+esc(i.id)+'"><strong>'+esc(i.name)+'</strong><small>'+esc(i.category)+'</small></button></div><select data-change="item-location" data-id="'+esc(i.id)+'" aria-label="Хранение: '+esc(i.name)+'">'+locations.map(l=>'<option value="'+esc(l)+'" '+(l===i.location?'selected':'')+'>'+l+'</option>').join('')+'</select><div class="quantity">'+button('qty','−','','data-id="'+esc(i.id)+'" data-delta="-1" aria-label="Уменьшить количество"')+'<span>'+i.qty+'</span>'+button('qty','＋','','data-id="'+esc(i.id)+'" data-delta="1" aria-label="Увеличить количество"')+'</div><span class="item-weight">'+(i.weight*i.qty).toLocaleString('ru-RU',{maximumFractionDigits:2})+'</span>'+button('delete-item','×','delete-button','data-id="'+esc(i.id)+'" aria-label="Удалить предмет"')+'</div>').join(''):'<div class="empty-state">Здесь пока ничего нет.</div>')+'</div><p class="edition-warning">Вес показан в килограммах. Вес монет и ограничения переноски пока учитывайте вручную.</p>'}
function notesView(){const c=character();return '<div class="notes-stack"><section class="panel"><div class="section-heading"><h3>Ваши заметки</h3><span class="tiny-label">СОХРАНЯЮТСЯ АВТОМАТИЧЕСКИ</span></div><textarea class="notes-area" id="notes" aria-label="Заметки персонажа" placeholder="Имена, зацепки, планы на следующую встречу…">'+esc(c.notes)+'</textarea><p class="notes-help">Заметки принадлежат этому персонажу и сохраняются в этом браузере.</p></section><section class="panel"><div class="section-heading"><h3>Журнал встреч</h3>'+button('journal','＋ Запись')+'</div>'+(c.journal.length?c.journal.map(j=>'<div class="journal-entry"><small>'+esc(j.date)+'</small><p data-no-i18n>'+esc(j.text)+'</p></div>').join(''):'<p class="muted">Запишите, чем закончилась сегодняшняя сессия.</p>')+'</section></div>'}

function currentCheckId(){if(!C.choices(character()).some(c=>c.id===state.checkSelection))state.checkSelection='skill:0';return state.checkSelection}
function checkBuilderView(){const c=character(),choice=currentCheckId();const grouped={};for(const o of C.choices(c))(grouped[o.group]??=[]).push(o);return '<section class="panel check-builder"><div class="section-heading"><h3>Проверка персонажа</h3><span class="tiny-label">МОДИФИКАТОРЫ УЧТЕНЫ</span></div><div class="check-controls"><label><span>Выберите навык, атаку или спасбросок</span><select id="check-choice" data-change="check-selection">'+Object.entries(grouped).map(([group,opts])=>'<optgroup label="'+esc(tr(group))+'">'+opts.map(o=>'<option value="'+o.id+'" '+(o.id===choice?'selected':'')+'>'+esc(o.name)+'</option>').join('')+'</optgroup>').join('')+'</select></label><label><span>Поправка к броску</span><input type="number" id="check-situation" min="-99" max="99" value="'+state.checkSituation+'"></label></div><div class="check-breakdown" id="check-breakdown"></div><div class="check-roll-line"><div><small>Итоговая формула</small><strong id="check-formula"></strong></div><select class="full-select" id="check-mode" data-change="check-mode" aria-label="Режим проверки">'+[['normal','Обычный бросок'],['advantage','С преимуществом · d20'],['disadvantage','С помехой · d20']].map(([id,n])=>'<option value="'+id+'" '+(state.checkMode===id?'selected':'')+'>'+tr(n)+'</option>').join('')+'</select>'+button('check-roll','Бросить проверку ↗','mint-button')+'</div><div class="section-heading" style="margin-top:24px"><h3>Активные эффекты</h3>'+button('effect-new','＋ Эффект','text-button')+'</div><div class="effect-list">'+(c.effects.length?c.effects.map(e=>'<div class="active-effect">'+button('effect-toggle',(e.active?'✓':'○')+' '+esc(e.name),'effect-toggle '+(e.active?'active':''),'data-id="'+esc(e.id)+'" aria-pressed="'+e.active+'"')+'<b>'+signed(e.value)+'</b>'+button('effect-edit','✎','text-button','data-id="'+esc(e.id)+'" aria-label="Изменить эффект"')+button('effect-delete','×','delete-button','data-id="'+esc(e.id)+'" aria-label="Удалить эффект"')+'</div>').join(''):'<p class="muted">Задайте бонус или штраф один раз — он будет учтён в нужных проверках.</p>')+'</div><p class="theme-hint">Бонусы вещей учитываются, когда предмет надет. Активные эффекты применяются к указанным проверкам. Условия применения и совместимость бонусов определяет мастер.</p></section>'}
function renderCheckSummary(){if(tab!=='dice')return;const check=C.calculate(character(),currentCheckId(),state.checkSituation);const el=$('#check-breakdown');if(el)el.innerHTML=translated(check.source.filter(x=>x.value!==0).map(x=>'<span class="check-source"><span>'+esc(x.label)+'</span><b class="'+(x.value<0?'negative':'')+'">'+signed(x.value)+'</b></span>').join('')||'<span class="muted">'+tr('Без модификаторов')+'</span>');const formula=$('#check-formula');if(formula)formula.textContent=check.formula;}
function rollCheck(id,situation=0,mode='normal'){const check=C.calculate(character(),id,situation);state.checkSelection=id;const result=doRoll(check.formula,check.name,mode,check);if(result){if(tab==='dice'){const choice=$('#check-choice');if(choice)choice.value=id;renderCheckSummary()}save()}return result}
function effectForm(effect){modal(effect?'Изменить эффект':'Новый эффект','<form id="effect-form" data-id="'+esc(effect?.id||'')+'"><div class="form-grid">'+field('Название','name',effect?.name||'','text',true,'maxlength="70"')+field('Бонус или штраф','value',effect?.value??1,'number',false,'min="-99" max="99"')+'<label class="form-field">Применять к<select name="target">'+C.targets(character()).map(t=>'<option value="'+t.id+'" '+(t.id===(effect?.target||'skill:*')?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></label></div><label class="form-check"><input type="checkbox" name="active" '+(!effect||effect.active?'checked':'')+'> Эффект активен</label><button class="mint-button modal-submit">Сохранить эффект</button></form>')}
function diceTrayView(){const t=state.tray,sides=[...new Set([...state.diceCollection.sides,...Object.keys(t.counts).filter(n=>t.counts[n]>0).map(Number)])],skin=D.skins[t.skin];return '<section class="panel dice-table"><div class="section-heading"><h3>Стол для кубиков</h3><span class="tiny-label">ВЫБЕРИТЕ · СОБЕРИТЕ · БРОСЬТЕ</span></div><div class="dice-counter-grid">'+sides.map(n=>'<div class="dice-counter '+(t.counts[n]>0?'selected':'')+'"><div class="counter-shape"><svg viewBox="0 0 80 80" aria-hidden="true">'+D.shape(n)+'</svg><span>d'+n+'</span></div><div class="counter-controls">'+button('tray-count','−','','data-sides="'+n+'" data-delta="-1" aria-label="Убрать d'+n+'" '+(!(t.counts[n]>0)?'disabled':''))+'<output aria-label="Количество d'+n+'">'+(t.counts[n]||0)+'</output>'+button('tray-count','＋','','data-sides="'+n+'" data-delta="1" aria-label="Добавить d'+n+'" '+(D.count(t)>=30?'disabled':''))+'</div></div>').join('')+'</div><div class="tray-options"><label>Общий бонус <input id="tray-bonus" type="number" min="-99" max="99" value="'+t.bonus+'"></label>'+button('tray-animation',(t.animation?'✓ ':'')+'Анимация','text-button','aria-pressed="'+t.animation+'"')+button('tray-clear','Очистить набор','text-button')+'</div><div class="dice-canvas" id="dice-canvas" data-skin="'+t.skin+'" aria-label="Поле броска кубиков" style="--die-fill:'+skin.fill+';--die-ink:'+skin.ink+';--die-line:'+skin.line+'"><div class="tray-watermark" aria-hidden="true">✧</div><div class="tray-empty"><span>Соберите свой бросок</span><small>Кубики появятся здесь</small></div></div><div class="tray-outcome" id="tray-outcome" aria-live="polite"></div><div class="tray-roll-controls"><div><span id="tray-formula">'+esc(D.formula(t)||tr('Добавьте кубики'))+'</span><small>'+D.count(t)+' / 30</small></div>'+button('tray-save','Сохранить пресет','outline-button')+button('tray-roll','Бросить набор ↗','mint-button')+'</div><div class="skin-heading"><span>Облик кубиков</span><small>ПРИМЕРЫ КОЛЛЕКЦИЙ</small></div><div class="dice-skins">'+Object.entries(D.skins).map(([id,s])=>button('tray-skin','<span class="skin-gem" style="--gem-fill:'+s.fill+';--gem-line:'+s.line+'"></span><span>'+s.name+'</span>','dice-skin '+(t.skin===id?'active':''),'data-id="'+id+'" aria-pressed="'+(t.skin===id)+'"')).join('')+'</div></section>'}
function renderTrayResult(result,animate=false){if(tab!=='dice')return;const canvas=$('#dice-canvas');if(!canvas)return;const t=state.tray;let dice;if(result)dice=D.diceFor(result);else dice=Object.entries(t.counts).flatMap(([sides,n])=>Array.from({length:n},()=>({sides:Number(sides),value:'?',kept:true})));if(!dice.length){canvas.innerHTML=translated('<div class="tray-watermark" aria-hidden="true">✧</div><div class="tray-empty"><span>Соберите свой бросок</span><small>Кубики появятся здесь</small></div>');$('#tray-outcome').innerHTML='';return;}const skin=D.skins[t.skin];canvas.style.setProperty('--die-fill',skin.fill);canvas.style.setProperty('--die-line',skin.line);canvas.style.setProperty('--die-ink',skin.ink);canvas.innerHTML='<div class="tray-watermark" aria-hidden="true">✧</div><div class="rolled-dice">'+dice.map((d,i)=>'<div class="tray-die '+(animate&&t.animation?'throwing':'')+' '+(!d.kept?'discarded':'')+'" style="--die-delay:'+((i%7)*35)+'ms;--entry-x:'+((i%3-1)*70)+'px;--entry-spin:'+(200+i*53)+'deg;--rest-spin:'+((i%5-2)*7)+'deg"><svg viewBox="0 0 80 80" aria-hidden="true">'+D.shape(d.sides)+'</svg><span class="die-number">'+d.value+'</span><small>d'+d.sides+'</small></div>').join('')+'</div>';$('#tray-outcome').innerHTML=result?translated('<div><span>Результат броска</span><strong>'+result.total+'</strong></div><p>'+esc(result.expression)+(result.chosen!==null&&result.chosen!==undefined?' · Выбранный кубик: '+result.chosen:'')+(result.bonus?' · Бонус '+signed(result.bonus):'')+'</p>'+(result.details?'<div class="tray-check-sources">'+result.details.source.filter(x=>x.value).map(x=>'<span>'+esc(x.label)+' '+signed(x.value)+'</span>').join('')+'</div>':'')):'';}

function diceView(){return diceTrayView()+checkBuilderView()+'<section class="panel dice-workbench"><div class="section-heading"><h3>Свой бросок</h3><span class="tiny-label">БЕЗ ЛИШНЕЙ АРИФМЕТИКИ</span></div><p class="muted">Смешивайте кубики и добавляйте бонус: 2d6+2d20+3.</p><form id="expression-form" class="expression-row"><input id="expression" placeholder="Например, 2d6+2d20+3" value="2d6+2d20" aria-label="Формула броска"><button class="mint-button" type="submit">Бросить ↗</button></form><div class="dice-save-row">'+button('save-roll','＋ Сохранить как пресет','text-button')+'</div><div class="section-heading" style="margin-top:23px"><h3>Мой набор кубиков</h3>'+button('dice-set','Настроить','text-button')+'</div><div class="collection-dice">'+state.diceCollection.sides.map(n=>button('die','d'+n,'collection-die '+(n===selectedDie?'selected':''),'data-sides="'+n+'"')).join('')+'</div><div class="section-heading" style="margin-top:26px"><h3>Ваши пресеты</h3>'+button('new-preset','＋ Пресет','text-button')+'</div><div class="custom-presets">'+(state.diceCollection.presets.length?state.diceCollection.presets.map(p=>'<article class="custom-preset"><button class="preset-main" data-action="roll-preset" data-id="'+esc(p.id)+'"><strong data-no-i18n>'+esc(p.name)+'</strong><span>'+esc(p.formula)+'</span><small>'+tr(p.mode==='advantage'?'С преимуществом · d20':p.mode==='disadvantage'?'С помехой · d20':'Обычный бросок')+'</small></button><div>'+button('edit-preset','✎','text-button','data-id="'+esc(p.id)+'" aria-label="Изменить пресет"')+button('delete-preset','×','delete-button','data-id="'+esc(p.id)+'" aria-label="Удалить пресет"')+'</div></article>').join(''):'<p class="muted">Сохраните бросок, который часто используете.</p>')+'</div><p class="dice-tip">Нажмите на пресет, чтобы бросить его. Смешанный бросок суммирует все кубики; преимущество и помеха доступны только для одного d20.</p></section>'}
function diceSetForm(){modal('Мой набор кубиков','<p class="modal-copy">Выберите кубики для быстрого броска. Можно добавить нестандартные грани, например d3 или d30.</p><form id="dice-set-form">'+field('Грани через запятую','sides',state.diceCollection.sides.map(n=>'d'+n).join(', '),'text',true,'maxlength="100"')+'<p class="theme-hint">До 12 типов кубиков, от d2 до d1000.</p><button class="mint-button modal-submit">Сохранить набор</button></form>')}
function presetForm(preset,formula='1d20'){modal(preset?'Изменить пресет':'Новый пресет','<form id="preset-form" data-id="'+esc(preset?.id||'')+'"><div class="form-grid">'+field('Название','name',preset?.name||'','text',true,'maxlength="70"')+field('Формула броска','formula',preset?.formula||formula,'text',true,'maxlength="120"')+'<label class="form-field wide">Режим броска<select name="mode">'+[['normal','Обычный бросок'],['advantage','С преимуществом · d20'],['disadvantage','С помехой · d20']].map(([id,name])=>'<option value="'+id+'" '+(preset?.mode===id?'selected':'')+'>'+name+'</option>').join('')+'</select></label></div><p class="theme-hint">Например: 1d20+5, 2d6+3 или 2d6+2d20. Максимум 30 кубиков за бросок.</p><button class="mint-button modal-submit">Сохранить пресет</button></form>')}

function renderHistory(){const history=state.history.filter(r=>r.characterId===state.active);$('#history').innerHTML=history.length?history.slice(0,4).map(r=>'<div class="history-item"><span>'+esc(r.label||r.expression)+'</span><strong>'+r.total+'</strong></div>').join(''):'<div class="history-empty">Здесь появится история бросков</div>';$('#dice-choices').innerHTML=state.diceCollection.sides.map(n=>button('die','d'+n,'dice-choice '+(n===selectedDie?'selected':''),'data-sides="'+n+'"')).join('');$('#roll-dice').innerHTML=tr('Бросить')+' d'+selectedDie+' <span>↗</span>';$('#roll-mode').disabled=selectedDie!==20||Number($('#dice-count').value)!==1;$('#history').innerHTML=translated($('#history').innerHTML);$('#quick-presets').innerHTML=translated(state.diceCollection.presets.slice(0,6).map(p=>button('roll-preset','<span>'+esc(p.name)+'</span><small>'+esc(p.formula)+'</small>','quick-preset','data-id="'+esc(p.id)+'"')).join(''));}
function doRoll(formula,label,mode='normal',details=null){try{const result=E.rollPool(formula,mode);if(details)result.details=details;lastTrayRoll=result;state.history.unshift({...result,label,characterId:state.active,date:Date.now()});state.history=state.history.slice(0,120);$('#dice-face').textContent=result.total;$('#dice-art').classList.remove('rolling');void $('#dice-art').offsetWidth;$('#dice-art').classList.add('rolling');$('#roll-result').innerHTML='<span>'+esc(label||formula)+(result.critical?' · Натуральная 20!':'')+'</span><strong>'+result.total+'</strong><small>'+result.values.join(' + ')+(mode!=='normal'?' → '+result.chosen:'')+(result.bonus?' '+signed(result.bonus):'')+'</small>';$('#roll-result').innerHTML=translated($('#roll-result').innerHTML);renderHistory();renderTrayResult(result,true);save();toast((label||formula)+': '+result.total);return result}catch(error){toast(error.message);return null}}
function modal(title,body){$('#modal-title').textContent=tr(title);$('#modal-body').innerHTML=translated(body);if(!$('#modal').open)$('#modal').showModal()}
const field=(label,name,value,type='text',wide=false,attrs='')=>'<label class="form-field '+(wide?'wide':'')+'">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+attrs+' required></label>';
const options=(arr,selected)=>arr.map(v=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('');
function characterForm(isNew){const c=character();modal(isNew?'Новый персонаж':'Изменить персонажа','<p class="modal-copy">'+(isNew?'Создайте пустой лист и внесите показатели из ваших правил. Можно также изучить готовые демонстрационные листы.':'Показатели можно поправить под вашу партию. Класс, уровень и экипировка пока не пересчитывают лист автоматически.')+'</p><form id="character-form" data-new="'+isNew+'"><div class="form-grid">'+field('Имя','name',isNew?'':c.name,'text',true,'maxlength="70"')+(isNew?'<label class="form-field wide">Редакция<select name="edition">'+Object.entries(E.editions).map(([id,name])=>'<option value="'+id+'" '+(id===c.edition?'selected':'')+'>'+name+'</option>').join('')+'</select></label>':'')+field('Класс','className',isNew?'Маг':c.className,'text',false,'maxlength="40"')+field('Вид / раса','race',isNew?'Человек':c.race,'text',false,'maxlength="40"')+field('Уровень','level',isNew?1:c.level,'number',false,'min="1" max="30"')+field('Максимум хитов','maxHp',isNew?10:c.maxHp,'number',false,'min="1" max="999"')+field('Класс доспеха','ac',isNew?10:c.ac,'number',false,'min="0" max="99"')+field('Скорость, м','speed',isNew?9:c.speed,'number',false,'min="0" max="999" step="0.5"')+E.labels.map((l,i)=>field(l,'stat'+i,isNew?10:c.stats[i],'number',false,'min="1" max="40"')).join('')+field('Бонус инициативы','initiative',isNew?0:c.initiative,'number',false,'min="-20" max="99"')+field(c.edition==='3.5'?'Базовый бонус атаки':'Бонус мастерства',c.edition==='3.5'?'baseAttack':'proficiency',isNew?2:c[c.edition==='3.5'?'baseAttack':'proficiency'],'number',false,'min="0" max="30"')+field('Бонус атаки заклинанием','spellAttack',isNew?2:c.spellAttack,'number',false,'min="-20" max="99"')+'<label class="form-field wide">Заклинательная характеристика<select name="spellAbility">'+E.labels.map((n,i)=>'<option value="'+i+'" '+(i===(c.spellAbility??3)?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+field('Сл заклинаний (5e)','spellDC',isNew?10:c.spellDC,'number',false,'min="1" max="99"')+'</div><button class="mint-button modal-submit" type="submit">'+(isNew?'Создать лист':'Сохранить изменения')+'</button></form>')}
function itemForm(item){modal(item?'Изменить предмет':'Добавить предмет','<form id="item-form" data-id="'+esc(item?.id||'')+'"><div class="form-grid">'+field('Русское название','name',item?.name||'','text',true,'maxlength="100"')+englishField(item?.englishName||'')+'<label class="form-field">Категория<select name="category">'+options(['Снаряжение','Оружие','Доспех','Расходник','Находка'],item?.category||'Снаряжение')+'</select></label><label class="form-field">Где хранится<select name="location">'+options(locations,item?.location||'Рюкзак')+'</select></label>'+field('Количество','qty',item?.qty??1,'number',false,'min="0" max="9999"')+field('Вес одной штуки, кг','weight',item?.weight??0,'number',false,'min="0" max="9999" step="0.01"')+''+field('Бонус к проверкам','bonusValue',item?.bonuses?.[0]?.value||0,'number',false,'min="-99" max="99"')+'<label class="form-field">Применять бонус к<select name="bonusTarget">'+C.targets(character()).map(t=>'<option value="'+t.id+'" '+(t.id===(item?.bonuses?.[0]?.target||'all')?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></label><label class="form-field wide">Описание<textarea name="desc" maxlength="1000">'+esc(item?.desc||'')+'</textarea></label></div><button class="mint-button modal-submit" type="submit">Сохранить предмет</button></form>')}
function spellForm(spell){modal(spell?'Изменить заклинание':'Добавить заклинание','<form id="spell-form" data-id="'+esc(spell?.id||'')+'"><div class="form-grid">'+field('Русское название','name',spell?.name||'','text',true,'maxlength="90"')+englishField(spell?.englishName||'')+field('Уровень (0 — заговор)','level',spell?.level??1,'number',false,'min="0" max="9"')+field('Школа','school',spell?.school||'Воплощение','text',false,'maxlength="40"')+field('Время применения','time',spell?.time||'Действие','text',false,'maxlength="40"')+field('Дальность','range',spell?.range||'9 м','text',false,'maxlength="40"')+'<label class="form-field wide">Формула урона (необязательно)<input name="damage" placeholder="2d6+3" value="'+esc(spell?.damage||'')+'"></label><label class="form-field wide">Описание<textarea name="desc" maxlength="1600">'+esc(spell?.desc||'')+'</textarea></label></div><label class="form-check"><input name="concentration" type="checkbox" '+(spell?.concentration?'checked':'')+'> Требует концентрации</label><label class="form-check"><input name="prepared" type="checkbox" '+(!spell||spell.prepared?'checked':'')+'> Подготовлено</label><button class="mint-button modal-submit" type="submit">Сохранить заклинание</button></form>')}
function restModal(){const c=character(),old=c.edition==='3.5';modal('Передохнём?','<p class="modal-copy">Восстановите ресурсы и продолжайте приключение. Состояния автоматически не снимаются.</p><div class="rest-options">'+(!old?button('short-rest','<strong>Короткий отдых · потратить кость хитов</strong><small>Осталось '+Math.max(0,c.hitDice.max-c.hitDice.used)+'d'+c.hitDice.sides+'. Лечение: кость + модификатор телосложения.</small>','rest-choice'):'')+button('long-rest','<strong>'+(old?'Отдых за сутки':'Продолжительный отдых')+'</strong><small>'+(old?'Лечение на '+c.level+' хитов, восстановление общих ячеек.': 'Полное здоровье и восстановление ячеек. Кости хитов: '+(c.edition==='5e2024'?'все':'половина максимума, минимум одна')+'.')+'</small>','rest-choice')+'</div><p class="edition-warning">Упрощённый учёт. Специальные ограничения и классовые эффекты контролирует мастер.</p>')}
function showInfo(){modal('Лист приключений','<p class="modal-copy">Помощник для живой игры в D&D. Это первая интерактивная версия: можно вести персонажа, бросать кубики, тратить ячейки, хранить вещи и записывать историю.</p><div class="info-row"><span>Редакции</span><strong>3.5 · 5e 2014 · 5e 2024</strong></div><div class="info-row"><span>Сохранение</span><strong>В этом браузере</strong></div><p class="modal-copy" style="margin-top:15px">Полная автоматизация правил пока не реализована. Создание и повышение уровня, эффекты экипировки, масштабирование заклинаний и ограничения отдыха требуют ручной проверки. В 3.5 ячейки пока учитываются общим счётчиком. Карточки заклинаний сокращённые — сверяйтесь с вашими правилами.</p><button class="mint-button modal-submit" id="info-export">Экспортировать активного персонажа</button>')}
function picker(){modal('Ваши персонажи',state.characters.map(c=>button('pick-character','<span><strong>'+esc(c.name)+'</strong><small>'+esc(c.className)+' · '+c.level+' ур. · '+E.editions[c.edition]+'</small></span><span>'+(c.id===state.active?'✓':'↗')+'</span>','character-option','data-id="'+esc(c.id)+'"')).join('')+button('new-character','＋ Создать персонажа','mint-button modal-submit'))}
function exportCharacter(){const c=character();const blob=new Blob([JSON.stringify({app:'adventure-ledger',version:1,character:c},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=c.name.replace(/[^\p{L}\p{N}_-]/gu,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Персонаж экспортирован')}
function action(action,element){const c=character(),id=element.dataset.id,index=Number(element.dataset.index),level=element.dataset.level;
switch(action){
case 'tray-count':{if(!D.change(state.tray,Number(element.dataset.sides),Number(element.dataset.delta))){toast('Максимум 30 кубиков за бросок');break}lastTrayRoll=null;render();break;}
case 'tray-clear':state.tray.counts={};state.tray.bonus=0;lastTrayRoll=null;render();break;
case 'tray-roll':{const formula=D.formula(state.tray);if(!formula){toast('Добавьте кубики стрелками');break}doRoll(formula,'Бросок набора');break;}
case 'tray-save':{const formula=D.formula(state.tray);if(!formula){toast('Добавьте кубики стрелками');break}presetForm(null,formula);break;}
case 'tray-skin':state.tray.skin=id;render();break;
case 'tray-animation':state.tray.animation=!state.tray.animation;render();break;
case 'check-roll':rollCheck(currentCheckId(),state.checkSituation,state.checkMode);break;
case 'effect-new':effectForm();break;
case 'effect-edit':effectForm(c.effects.find(e=>e.id===id));break;
case 'effect-toggle':{const effect=c.effects.find(e=>e.id===id);effect.active=!effect.active;render();break;}
case 'effect-delete':c.effects=c.effects.filter(e=>e.id!==id);render();break;
case 'dice-set':diceSetForm();break;
case 'new-preset':presetForm();break;
case 'save-roll':presetForm(null,$('#expression')?.value||'1d20');break;
case 'edit-preset':presetForm(state.diceCollection.presets.find(p=>p.id===id));break;
case 'roll-preset':{const p=state.diceCollection.presets.find(p=>p.id===id);if(p)doRoll(p.formula,p.name,p.mode);break}
case 'delete-preset':modal('Удалить пресет?','<p class="modal-copy">'+esc(state.diceCollection.presets.find(p=>p.id===id).name)+'</p>'+button('confirm-delete-preset','Удалить','mint-button modal-submit','data-id="'+esc(id)+'"'));break;
case 'confirm-delete-preset':state.diceCollection.presets=state.diceCollection.presets.filter(p=>p.id!==id);$('#modal').close();render();break;
case 'language':$('#language').onchange({target:{value:id}});break;
case 'theme-preset':if(T.presets[id]){state.theme=T.normalize(T.presets[id]);render();toast('Тема обновлена')}break;
case 'theme-icon-style':state.theme.iconStyle=id;render();break;
case 'theme-pattern':state.theme.pattern=id;render();break;
case 'theme-atmosphere':state.theme.atmosphere=id;render();break;
case 'theme-panels':state.theme.panels=id;render();break;
case 'theme-motion':state.theme.motion=!state.theme.motion;render();break;
case 'theme-reset':modal('Вернуть лесную тему?','<p class="modal-copy">Будут сброшены только цвета, узор и стиль иконок.</p>'+button('theme-confirm-reset','Сбросить тему','mint-button modal-submit'));break;
case 'theme-confirm-reset':state.theme={...T.defaults};$('#modal').close();render();toast('Тема сброшена');break;
case 'tab':tab=id;location.hash=id;render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'picker':picker();break;
case 'pick-character':state.active=id;lastTrayRoll=null;$('#modal').close();$('#roll-result').innerHTML='<span>Сделайте первый бросок</span><small>История сохраняется для каждого персонажа</small>';render();break;
case 'new-character':characterForm(true);break;
case 'edit-character':characterForm(false);break;
case 'combat':combat=!combat;render();break;
case 'die':selectedDie=Number(element.dataset.sides);$('#dice-face').textContent=selectedDie;if(selectedDie!==20)$('#roll-mode').value='normal';renderHistory();break;
case 'damage':case 'heal':{const amount=E.integer($('#hp-amount').value,1,999,1);E.applyHp(c,action==='damage'?-amount:amount);render();toast(action==='damage'?'Урон учтён':'Здоровье восстановлено');break}
case 'temp-hp':modal('Временные хиты','<form id="number-form" data-field="tempHp">'+field('Новое значение (заменяет прежнее)','value',c.tempHp,'number',true,'min="0" max="999"')+'<button class="mint-button modal-submit">Сохранить</button></form>');break;
case 'initiative':doRoll('1d20'+signed(C.calculate(c,'initiative').bonus),'Инициатива');break;
case 'ability':rollCheck('ability:'+index);break;
case 'skill':rollCheck('skill:'+index);break;
case 'save':rollCheck('save:'+index);break;
case 'attack':rollCheck('attack:'+id);break;
case 'slot':{const slot=c.slots[level];slot.used=index<slot.used?Math.max(0,slot.used-1):Math.min(slot.max,slot.used+1);render();break}
case 'resource':c.resource.used=c.resource.used>=c.resource.max?0:c.resource.used+1;render();break;
case 'turn':c.turn[id]=!c.turn[id];render();break;
case 'reset-turn':c.turn.action=false;c.turn.bonus=false;if(c.edition==='3.5')c.turn.reaction=false;render();toast(c.edition==='3.5'?'Действия нового хода восстановлены.':'Действия нового хода восстановлены. Реакцию отмечайте отдельно.');break;
case 'rest':restModal();break;
case 'long-rest':E.rest(c,'long');$('#modal').close();render();toast('Отдых завершён');break;
case 'short-rest':if(c.hitDice.used>=c.hitDice.max){toast('Кости хитов закончились');break} {const r=doRoll('1d'+c.hitDice.sides+signed(E.modifier(c.stats[2])),'Короткий отдых');if(r){c.hitDice.used++;E.applyHp(c,Math.max(0,r.total));$('#modal').close();render();}}break;
case 'conditions':{const choices=['Ослеплён','Очарован','Оглушён','Испуган','Отравлен','Лежит ничком','Обездвижен','Невидим','Без сознания'];modal('Состояния персонажа','<p class="modal-copy">Метки для учёта. Модификаторы состояния внесите вручную.</p><div class="filters">'+choices.map(n=>button('add-condition',esc(n),'filter-button '+(c.conditions.includes(n)?'active':''),'data-id="'+esc(n)+'"')).join('')+'</div>');break}
case 'add-condition':c.conditions=c.conditions.includes(id)?c.conditions.filter(n=>n!==id):[...c.conditions,id];render();element.classList.toggle('active');break;
case 'remove-condition':c.conditions=c.conditions.filter(n=>n!==id);render();break;
case 'edit-skills':modal('Навыки и спасброски','<form id="skills-form"><p class="modal-copy">'+(c.edition==='3.5'?'Бонус умения = ранги + модификатор характеристики.':'Бонус навыка = модификатор характеристики + мастерство при владении.')+'</p>'+c.skills.map((s,i)=>c.edition==='3.5'?field(esc(s.name)+' — ранги','rank'+i,s.rank,'number',true,'min="0" max="50"'):'<label class="form-check"><input type="checkbox" name="skill'+i+'" '+(s.trained?'checked':'')+'> '+esc(s.name)+'</label><label class="form-check expertise-check"><input type="checkbox" name="expert'+i+'" '+(s.expertise?'checked':'')+'> Компетентность: '+esc(s.name)+'</label>').join('')+'<p class="modal-copy" style="margin-top:16px">Спасброски</p>'+(c.edition==='3.5'?['Стойкость','Рефлексы','Воля'].map((n,i)=>field(n+' — базовый бонус','save'+i,c.oldSaves[i],'number',true,'min="0" max="50"')).join(''):E.labels.map((n,i)=>'<label class="form-check"><input type="checkbox" name="save'+i+'" '+(c.saveTraining[i]?'checked':'')+'> Владение: '+n+'</label>').join(''))+'<button class="mint-button modal-submit">Сохранить</button></form>');break;
case 'slots':modal('Ячейки и ресурсы','<form id="slots-form"><div class="form-grid">'+Array.from({length:c.edition==='3.5'?10:9},(_,index)=>{const i=index+(c.edition==='3.5'?0:1);return field('Ячеек '+i+' уровня','slot'+i,c.slots[i]?.max||0,'number',false,'min="0" max="12"')}).join('')+field('Название ресурса','resourceName',c.resource.name,'text',true,'maxlength="50"')+field('Использований ресурса','resourceMax',c.resource.max,'number',false,'min="0" max="20"')+field('Максимум костей хитов','hitDiceMax',c.hitDice.max,'number',false,'min="0" max="30"')+'</div><button class="mint-button modal-submit">Сохранить</button></form>');break;
case 'spell-filter':spellFilter=id;render();break;
case 'prepare':{const s=c.spells.find(s=>s.id===id);s.prepared=!s.prepared;render();break}
case 'cast':{const s=c.spells.find(s=>s.id===id);if(!s.prepared){toast('Сначала подготовьте заклинание');break}if(s.level===0&&c.edition!=='3.5'){resolveCast(s,0);break}const available=Object.entries(c.slots).filter(([n,slot])=>+n>=s.level&&slot.used<slot.max);if(!available.length){toast('Нет подходящих свободных ячеек');break}modal('Сотворить: '+s.name,'<p class="modal-copy">Выберите ячейку. Урон при повышении уровня ячейки нужно скорректировать вручную.</p><div class="rest-options">'+available.map(([n,slot])=>button('cast-level','<strong>Ячейка '+n+' уровня</strong><small>Осталось '+(slot.max-slot.used)+' из '+slot.max+'</small>','rest-choice','data-id="'+esc(s.id)+'" data-level="'+n+'"')).join('')+'</div>'+(s.concentration&&c.concentration?'<p class="edition-warning">Текущая концентрация «'+esc(c.concentration)+'» будет заменена.</p>':''));break}
case 'cast-level':resolveCast(c.spells.find(s=>s.id===id),Number(level));break;
case 'spell-details':{const s=c.spells.find(s=>s.id===id);modal(s.name,'<p class="modal-copy">'+esc(s.desc)+'</p><div class="info-row"><span>Уровень / школа</span><strong>'+s.level+' / '+esc(s.school)+'</strong></div><div class="info-row"><span>Применение</span><strong>'+esc(s.time)+'</strong></div><div class="info-row"><span>Дальность</span><strong>'+esc(s.range)+'</strong></div>'+(s.damage?'<div class="info-row"><span>Базовый урон</span><strong>'+esc(s.damage)+'</strong></div>':'')+'<div class="filters" style="margin-top:20px">'+(s.damage?button('spell-damage','Бросить урон','filter-button','data-id="'+esc(id)+'"'):'')+button('edit-spell','Изменить','filter-button','data-id="'+esc(id)+'"')+button('delete-spell','Удалить','filter-button','data-id="'+esc(id)+'"')+'</div>');break}
case 'spell-damage':doRoll(c.spells.find(s=>s.id===id).damage,'Урон: '+c.spells.find(s=>s.id===id).name);$('#modal').close();break;
case 'new-spell':spellForm();break;
case 'edit-spell':spellForm(c.spells.find(s=>s.id===id));break;
case 'delete-spell':modal('Удалить заклинание?','<p class="modal-copy">Карточка будет удалена из книги этого персонажа.</p>'+button('confirm-delete-spell','Удалить','mint-button modal-submit','data-id="'+esc(id)+'"'));break;
case 'confirm-delete-spell':c.spells=c.spells.filter(s=>s.id!==id);$('#modal').close();render();break;
case 'end-concentration':c.concentration=null;render();break;
case 'inventory-filter':inventoryFilter=id;render();break;
case 'new-item':itemForm();break;
case 'edit-item':itemForm(c.items.find(i=>i.id===id));break;
case 'qty':{const i=c.items.find(i=>i.id===id);i.qty=E.integer(i.qty+Number(element.dataset.delta),0,9999);render();break}
case 'delete-item':modal('Удалить предмет?','<p class="modal-copy">'+esc(c.items.find(i=>i.id===id).name)+' будет удалён из инвентаря.</p>'+button('confirm-delete-item','Удалить','mint-button modal-submit','data-id="'+esc(id)+'"'));break;
case 'confirm-delete-item':c.items=c.items.filter(i=>i.id!==id);$('#modal').close();render();break;
case 'item-details':{const i=c.items.find(i=>i.id===id);modal(i.name,'<p class="modal-copy">'+esc(i.desc||'Описание пока не добавлено.')+'</p><div class="info-row"><span>Хранение</span><strong>'+esc(i.location)+'</strong></div><div class="info-row"><span>Количество</span><strong>'+i.qty+'</strong></div><div class="filters" style="margin-top:20px">'+button('edit-item','Изменить','filter-button','data-id="'+esc(id)+'"')+(i.id==='potion'?button('potion','Выпить · 2d4+2','filter-button','data-id="'+esc(id)+'"'):'')+'</div>');break}
case 'potion':{const i=c.items.find(i=>i.id===id);if(i.qty<1){toast('Зелья закончились');break}const r=doRoll('2d4+2','Зелье лечения');if(r){i.qty--;E.applyHp(c,r.total);$('#modal').close();render();}}break;
case 'money':modal('Золотые монеты','<form id="number-form" data-field="money">'+field('Количество','value',c.money,'number',true,'min="0" max="9999999"')+'<button class="mint-button modal-submit">Сохранить</button></form>');break;
case 'journal':modal('Новая запись','<form id="journal-form"><label class="form-field">Что произошло на встрече?<textarea name="text" maxlength="4000" required placeholder="Сегодня мы…"></textarea></label><button class="mint-button modal-submit">Добавить запись</button></form>');break;
case 'preset':doRoll(element.dataset.formula);break;
}
}
function resolveCast(spell,level){const c=character();if(!E.cast(c,spell,level)){toast('Ячейка уже потрачена');return}if(spell.concentration)c.concentration=spell.name;c.turn[spell.time==='Бонусное действие'?'bonus':spell.time==='Реакция'?'reaction':'action']=true;if($('#modal').open)$('#modal').close();render();if(spell.damage)doRoll(spell.damage,'Урон: '+spell.name);else toast(spell.name+': использовано');}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el)action(el.dataset.action,el)});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.change==='check-selection'){state.checkSelection=el.value;renderCheckSummary();save();return;}if(el.dataset.change==='check-mode'){state.checkMode=el.value;save();return;}if(el.dataset.themeSetting){updateThemeSetting(el);return;}if(el.dataset.themeField){updateThemeInput(el);return;}if(el.dataset.change==='item-location'){character().items.find(i=>i.id===el.dataset.id).location=el.value;render();toast('Место хранения изменено')}});
document.addEventListener('input',event=>{if(event.target.id==='tray-bonus'){state.tray.bonus=E.integer(event.target.value,-99,99);save();const el=$('#tray-formula');if(el)el.textContent=D.formula(state.tray)||tr('Добавьте кубики');return;}if(event.target.id==='check-situation'){state.checkSituation=E.integer(event.target.value,-99,99);renderCheckSummary();save();return;}if(event.target.dataset?.themeSetting){updateThemeSetting(event.target);return;}if(event.target.dataset?.themeField){updateThemeInput(event.target);return;}if(event.target.id==='notes'){character().notes=event.target.value;save()}if(event.target.id==='spell-search'){spellQuery=event.target.value;const start=event.target.selectionStart;$('#view').innerHTML=translated(spellsView());$('#spell-search').focus();$('#spell-search').setSelectionRange(start,start)}if(event.target.id==='dice-count')renderHistory()});
document.addEventListener('submit',event=>{const form=event.target;if(!form.id)return;event.preventDefault();const data=new FormData(form),c=character(),value=name=>data.get(name),number=(name,min,max,fallback=0)=>E.integer(value(name),min,max,fallback);switch(form.id){
case 'effect-form':{const id=form.dataset.id;const effect={id:id||'effect-'+crypto.randomUUID(),name:String(value('name')).trim(),value:number('value',-99,99),target:value('target'),active:data.has('active')};if(!C.targets(c).some(t=>t.id===effect.target)){toast('Выберите проверку');return}if(id)c.effects[c.effects.findIndex(e=>e.id===id)]=effect;else c.effects.push(effect);break;}
case 'expression-form':doRoll($('#expression').value);return;
case 'dice-set-form':{const raw=String(value('sides')).split(/[,;\s]+/).filter(Boolean);const sides=[...new Set(raw.map(v=>Number(v.replace(/^d/i,''))))];if(!sides.length||sides.length>12||sides.some(v=>!Number.isInteger(v)||v<2||v>1000)){toast('Укажите до 12 кубиков: от d2 до d1000');return}state.diceCollection.sides=sides;if(!sides.includes(selectedDie))selectedDie=sides[0];$('#dice-face').textContent=selectedDie;break;}
case 'preset-form':{const formula=String(value('formula')).trim(),mode=value('mode');try{const p=E.parsePool(formula);if(mode!=='normal'&&(p.parts.length!==1||p.parts[0].sides!==20||p.parts[0].count!==1))throw new Error('Преимущество и помеха доступны для 1d20')}catch(e){toast(e.message);return}const id=form.dataset.id;const preset={id:id||'preset-'+crypto.randomUUID(),name:String(value('name')).trim().slice(0,70),formula:E.parsePool(formula).expression,mode};if(id)state.diceCollection.presets[state.diceCollection.presets.findIndex(p=>p.id===id)]=preset;else state.diceCollection.presets.push(preset);break;}
case 'number-form':c[form.dataset.field]=number('value',0,form.dataset.field==='money'?9999999:999);break;
case 'character-form':{const isNew=form.dataset.new==='true';let target=isNew?E.createCharacter(value('edition'),value('name').trim()):c;if(isNew){target.demo=false;target.items=[];target.spells=[];target.notes='';target.journal=[];target.money=0;target.slots={1:{max:0,used:0},2:{max:0,used:0},3:{max:0,used:0}};target.resource={name:'Классовый ресурс',max:0,used:0};target.skills.forEach(s=>{s.trained=false;s.rank=0});target.oldSaves=[0,0,0];target.saveTraining=[false,false,false,false,false,false]};target.name=value('name').trim();target.className=value('className').trim();target.race=value('race').trim();target.level=number('level',1,30,1);target.maxHp=number('maxHp',1,999,10);target.hp=isNew?target.maxHp:Math.min(target.hp,target.maxHp);target.ac=number('ac',0,99,10);target.speed=Math.max(0,Math.min(999,Number(value('speed'))||0));target.stats=E.labels.map((_,i)=>number('stat'+i,1,40,10));target.initiative=number('initiative',-20,99);target.proficiency=number('proficiency',0,30,2);target.baseAttack=number('baseAttack',0,30);target.spellAttack=number('spellAttack',-20,99);target.spellDC=number('spellDC',1,99,10);target.spellAbility=number('spellAbility',0,5,3);target.spellAttackAdjustment=target.spellAttack-(E.modifier(target.stats[target.spellAbility])+target.proficiency);target.initiativeAdjustment=target.initiative-E.modifier(target.stats[1]);if(isNew){target.hitDice.max=target.level;state.characters.push(target);state.active=target.id;tab='character';location.hash=tab}break}
case 'skills-form':c.skills.forEach((s,i)=>{if(c.edition==='3.5')s.rank=number('rank'+i,0,50);else {s.expertise=data.has('expert'+i);s.trained=data.has('skill'+i)||s.expertise;}});if(c.edition==='3.5')c.oldSaves=c.oldSaves.map((_,i)=>number('save'+i,0,50));else c.saveTraining=c.saveTraining.map((_,i)=>data.has('save'+i));break;
case 'slots-form':for(let i=c.edition==='3.5'?0:1;i<=9;i++){const max=number('slot'+i,0,12);c.slots[i]={max,used:Math.min(c.slots[i]?.used||0,max)}}c.resource.name=value('resourceName');c.resource.max=number('resourceMax',0,20);c.resource.used=Math.min(c.resource.used,c.resource.max);c.hitDice.max=number('hitDiceMax',0,30);c.hitDice.used=Math.min(c.hitDice.used,c.hitDice.max);break;
case 'item-form':{const id=form.dataset.id;const item={id:id||'item-'+crypto.randomUUID(),bonuses:number('bonusValue',-99,99)?[{target:value('bonusTarget'),value:number('bonusValue',-99,99)}]:[],name:value('name').trim(),englishName:String(value('englishName')||'').trim().slice(0,100),category:value('category'),location:value('location'),qty:number('qty',0,9999,1),weight:Math.max(0,Math.min(9999,Number(value('weight'))||0)),desc:value('desc')};if(id)c.items[c.items.findIndex(i=>i.id===id)]=item;else c.items.push(item);break}
case 'spell-form':{if(value('damage').trim()&&!/^\d{1,2}d\d{1,4}([+-]\d{1,3})?$/i.test(value('damage').trim())){toast('Формула урона: например 2d6+3');return}const id=form.dataset.id,spell={id:id||'spell-'+crypto.randomUUID(),name:value('name').trim(),englishName:String(value('englishName')||'').trim().slice(0,100),level:number('level',0,9,1),school:value('school').trim(),time:value('time').trim(),range:value('range').trim(),damage:value('damage').trim(),desc:value('desc'),concentration:data.has('concentration'),prepared:data.has('prepared')};if(id)c.spells[c.spells.findIndex(s=>s.id===id)]=spell;else c.spells.push(spell);break}
case 'journal-form':c.journal.unshift({text:value('text').trim(),date:new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})});break;
}
$('#modal').close();render();toast('Сохранено');});
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('#modal').close()}});
$('#character-picker').onclick=picker;$('#new-character').onclick=()=>characterForm(true);$('#edit-character').onclick=()=>characterForm(false);$('#rest').onclick=restModal;$('#settings').onclick=showInfo;$('#export').onclick=exportCharacter;document.addEventListener('click',event=>{if(event.target.id==='info-export')exportCharacter()});
$('#edition').onchange=event=>{const next=state.characters.find(c=>c.edition===event.target.value);if(next){state.active=next.id;lastTrayRoll=null;spellQuery='';spellFilter='all';inventoryFilter='all';$('#roll-result').innerHTML='<span>Сделайте первый бросок</span><small>История сохраняется для каждого персонажа</small>';render();toast('Открыт лист: '+E.editions[next.edition]);}};
$('#roll-dice').onclick=()=>{const count=E.integer($('#dice-count').value,1,30,1),bonus=E.integer($('#dice-mod').value,-99,99);$('#dice-count').value=count;$('#dice-mod').value=bonus;doRoll(count+'d'+selectedDie+signed(bonus),null,selectedDie===20&&count===1?$('#roll-mode').value:'normal')};
$('#clear-history').onclick=()=>{state.history=state.history.filter(r=>r.characterId!==state.active);renderHistory();save();toast('История этого персонажа очищена')};
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(navigation.some(n=>n[0]===next)&&next!==tab){tab=next;render()}});
$('#language').onchange=event=>{state.language=['ru','en','bilingual'].includes(event.target.value)?event.target.value:'ru';refreshLanguage();render();toast('Язык сохранён')};
refreshLanguage();
render();
